import{_ as t,c as a,o as i,ag as r}from"./chunks/framework.DQvKz0xt.js";const p=JSON.parse('{"title":"数据绑定概览 (Data Binding Overview) - Rive 编辑器","description":"数据绑定 (Data Binding) 通过视图模型 (View Models) 将编辑器元素连接到数据和代码。","frontmatter":{"title":"数据绑定概览 (Data Binding Overview) - Rive 编辑器","description":"数据绑定 (Data Binding) 通过视图模型 (View Models) 将编辑器元素连接到数据和代码。","head":[["meta",{"name":"keywords","content":"Rive, Rive 中文文档, Rive 编辑器, 数据绑定, 数据绑定概览"}]]},"headers":[],"relativePath":"editor/data-binding/overview.md","filePath":"editor/data-binding/overview.md","lastUpdated":1774838907000}'),n={name:"editor/data-binding/overview.md"};function d(l,e,o,s,h,c){return i(),a("div",null,[...e[0]||(e[0]=[r('<p>数据绑定 (Data Binding)</p><h1 id="数据绑定概览-data-binding-overview" tabindex="-1">数据绑定概览 (Data Binding Overview) <a class="header-anchor" href="#数据绑定概览-data-binding-overview" aria-label="Permalink to &quot;数据绑定概览 (Data Binding Overview)&quot;">​</a></h1><p>通过视图模型 (View Models) 将编辑器元素连接到数据和代码。</p><h1 id="​-什么是数据绑定" tabindex="-1"><a href="#what-is-data-binding">​</a> 什么是数据绑定？ <a class="header-anchor" href="#​-什么是数据绑定" aria-label="Permalink to &quot;[​](#what-is-data-binding) 什么是数据绑定？&quot;">​</a></h1><p>数据绑定是一种在编辑器元素、数据和代码之间建立“响应式连接”的强大方式。例如，你可以：</p><ul><li>将图标的颜色绑定到一个“颜色数据属性”，以便开发者在运行时进行调整。</li><li>绑定动画对象的 X 轴位置，以便另一个对象能以一定的偏移量跟随它。</li><li>监听两个按钮的点击事件，从而增加或减少一个计数器。</li></ul><h1 id="​-为什么要使用数据绑定" tabindex="-1"><a href="#why-use-data-binding">​</a> 为什么要使用数据绑定？ <a class="header-anchor" href="#​-为什么要使用数据绑定" aria-label="Permalink to &quot;[​](#why-use-data-binding) 为什么要使用数据绑定？&quot;">​</a></h1><p>数据绑定通过引入“中间数据（即契约）”来解耦设计和代码。一旦这个“契约”建立，设计师和开发者就可以独立迭代，从而加快交付速度。 在编辑器内部，数据绑定能让你的设计具备极强的“反应能力”。你可以建立对象间的关联，并确保无论画板处于何种状态，特定的对应关系始终成立。数据绑定系统将确保这些关系在动画或代码调用改变值时始终保持最新。 此外，它还允许你将更多的逻辑从代码转移到 Rive 文件中。虽然你需要决定某段逻辑是留在代码中还是放在数据绑定里，但一个核心优势是：<strong>数据绑定逻辑在所有运行时中都是通用的</strong>，不需要针对不同平台（如 iOS 和 Web）重复实现。</p><h1 id="​-术语表-glossary" tabindex="-1"><a href="#glossary">​</a> 术语表 (Glossary) <a class="header-anchor" href="#​-术语表-glossary" aria-label="Permalink to &quot;[​](#glossary) 术语表 (Glossary)&quot;">​</a></h1><p>数据绑定引入了几个你需要熟悉的术语。这些名称借鉴了软件开发中的 <strong>MVVM (Model, View, Viewmodel)</strong> 模式。</p><h3 id="​-编辑器元素-editor-element" tabindex="-1"><a href="#editor-element">​</a> 编辑器元素 (Editor Element) <a class="header-anchor" href="#​-编辑器元素-editor-element" aria-label="Permalink to &quot;[​](#editor-element) 编辑器元素 (Editor Element)&quot;">​</a></h3><p>指编辑器中任何可编辑的 UI 元素，其属性值可以挂载绑定。</p><h3 id="​-视图模型-view-model" tabindex="-1"><a href="#view-model">​</a> 视图模型 (View Model) <a class="header-anchor" href="#​-视图模型-view-model" aria-label="Permalink to &quot;[​](#view-model) 视图模型 (View Model)&quot;">​</a></h3><p>视图模型是数据的蓝图。开发者可以将其理解为面向对象编程中的“类 (Class)”。视图模型通常描述了特定用例（通常是每个画板一个）的所有关联数据。视图模型本身不含具体数值，包含具体数值的是 <a href="#view-model-instance">实例 (Instance)</a>。</p><h3 id="​-视图模型属性-view-model-property" tabindex="-1"><a href="#view-model-property">​</a> 视图模型属性 (View Model Property) <a class="header-anchor" href="#​-视图模型属性-view-model-property" aria-label="Permalink to &quot;[​](#view-model-property) 视图模型属性 (View Model Property)&quot;">​</a></h3><p>视图模型中的单个数据项，类似于类中的“字段 (Field)”。属性在创建时会选择数据类型，并赋予一个可在代码中引用的名称。</p><h3 id="​-视图模型实例-view-model-instance" tabindex="-1"><a href="#view-model-instance">​</a> 视图模型实例 (View Model Instance) <a class="header-anchor" href="#​-视图模型实例-view-model-instance" aria-label="Permalink to &quot;[​](#view-model-instance) 视图模型实例 (View Model Instance)&quot;">​</a></h3><p>视图模型的“活”样本，带有实际数值。一个视图模型可以创建无数个实例。例如，如果你有一个包含三个按钮的菜单：🏠 首页、👤 个人资料、❓ 关于，你可以只有一个画板（菜单项模板），但创建三个对应不同图标和文字的“视图模型实例”。</p><h3 id="​-绑定-binding" tabindex="-1"><a href="#binding">​</a> 绑定 (Binding) <a class="header-anchor" href="#​-绑定-binding" aria-label="Permalink to &quot;[​](#binding) 绑定 (Binding)&quot;">​</a></h3><p>属性与编辑器元素之间的关联。</p><ul><li><strong>默认绑定 (Source to Target)</strong>：属性值的变化驱动元素更新（如：XPos 属性更新位置）。</li><li><strong>反向绑定 (Target to Source)</strong>：元素值的变化驱动属性更新。</li><li><strong>双向绑定 (Bidirectional)</strong>：双向同步，任何一方改变都会更新另一方。</li></ul><h3 id="​-转换器-converter" tabindex="-1"><a href="#converter">​</a> 转换器 (Converter) <a class="header-anchor" href="#​-转换器-converter" aria-label="Permalink to &quot;[​](#converter) 转换器 (Converter)&quot;">​</a></h3><p>转换器用于在应用绑定时对值进行转换。例如，使用“转换为字符串”转换码，将数字位置信息转换为文本显示在文本框中。</p><h1 id="​-与现有功能对比" tabindex="-1"><a href="#comparing-to-existing-features">​</a> 与现有功能对比 <a class="header-anchor" href="#​-与现有功能对比" aria-label="Permalink to &quot;[​](#comparing-to-existing-features) 与现有功能对比&quot;">​</a></h1><p>数据绑定是输入 (Inputs) 和事件 (Events) 的更强大替代方案。我们建议在未来的大多数用例中采用它。</p><table tabindex="0"><thead><tr><th>特性支持</th><th style="text-align:center;">输入 (Inputs)</th><th style="text-align:center;">事件 (Events)</th><th style="text-align:center;">视图模型属性</th></tr></thead><tbody><tr><td>浮点数/布尔值</td><td style="text-align:center;">✅</td><td style="text-align:center;">✅</td><td style="text-align:center;">✅</td></tr><tr><td>触发器 (Triggers)</td><td style="text-align:center;">✅</td><td style="text-align:center;">❌</td><td style="text-align:center;">✅</td></tr><tr><td>字符串 (Strings)</td><td style="text-align:center;">❌</td><td style="text-align:center;">✅</td><td style="text-align:center;">✅</td></tr><tr><td>枚举 (Enums)/颜色</td><td style="text-align:center;">❌</td><td style="text-align:center;">❌</td><td style="text-align:center;">✅</td></tr><tr><td>嵌套/列表/图像</td><td style="text-align:center;">❌</td><td style="text-align:center;">❌</td><td style="text-align:center;">✅</td></tr></tbody></table><h3 id="​-状态机输入" tabindex="-1"><a href="#state-machine-inputs">​</a> 状态机输入 <a class="header-anchor" href="#​-状态机输入" aria-label="Permalink to &quot;[​](#state-machine-inputs) 状态机输入&quot;">​</a></h3><p>在数据绑定之前，输入是主要的交互方式。但输入只能驱动状态机过渡，而数据绑定可以驱动 Rive 中的<strong>绝大多数编辑器元素</strong>（如颜色、透明度、位置等）。</p><h3 id="​-事件" tabindex="-1"><a href="#events">​</a> 事件 <a class="header-anchor" href="#​-事件" aria-label="Permalink to &quot;[​](#events) 事件&quot;">​</a></h3><p>事件主要是为了让设计向代码发送“信号（输出）”。数据绑定提供了一个更丰富的通道。虽然事件依然支持播放音效（数据绑定暂不支持），但在大多数逻辑层面，视图模型属性更具优势。</p><h1 id="​-运行时-api" tabindex="-1"><a href="#runtime-apis">​</a> 运行时 API <a class="header-anchor" href="#​-运行时-api" aria-label="Permalink to &quot;[​](#runtime-apis) 运行时 API&quot;">​</a></h1><p>要了解如何在代码中与数据绑定交互，请参阅 <a href="/docs/runtimes/data-binding">运行时概览</a> 页面。</p><p><a href="/docs/editor/events/audio-events">音频事件</a><a href="https://help.rive.app/editor/data-binding/lists" target="_blank" rel="noreferrer">列表</a></p>',33)])])}const v=t(n,[["render",d]]);export{p as __pageData,v as default};
